select v.codigo, v.nombre, cl.id, em.id, v.estado, v.inicio::date, v.cierre::date, v.notas
from (values
('PT505', 'Escápate del estrés', 'Compensar', 'Consorcio Salud', 'Finalizado', '2026-07-18', '2026-07-27', 'Presentación personal y respetar el tiempo asignado.'),
