from (values
('COT-001', 'Compensar', 'Consorcio Salud', 'Escápate del estrés', '2026-07-16', 50.0, 5950.0, 297500.0, 1.0, 280000.0, 280000.0, 577500.0, 670624.5006068998, 0.15401818181818186, 'Aprobada'),
